CREATE TABLE public.rosa_conversas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), funcionario_id uuid NOT NULL UNIQUE REFERENCES public.funcionarios(id), tenant_id uuid, pedido_ativo uuid, iniciado_em timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.rosa_conversas TO service_role;
ALTER TABLE public.rosa_conversas ENABLE ROW LEVEL SECURITY;
CREATE POLICY rosa_conversas_servidor ON public.rosa_conversas FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE TABLE public.rosa_mensagens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversa_id uuid NOT NULL REFERENCES public.rosa_conversas(id), pedido_id uuid NOT NULL, papel text NOT NULL CHECK(papel IN ('user','assistant')), partes jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(conversa_id,pedido_id,papel));
GRANT ALL ON public.rosa_mensagens TO service_role;
ALTER TABLE public.rosa_mensagens ENABLE ROW LEVEL SECURITY;
CREATE POLICY rosa_mensagens_servidor ON public.rosa_mensagens FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.rosa_orientacoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid, proposta text NOT NULL, orientacao_aprovada text, status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','aprovada','rejeitada')), revisado_por uuid, revisado_em timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.rosa_orientacoes TO authenticated;
GRANT ALL ON public.rosa_orientacoes TO service_role;
ALTER TABLE public.rosa_orientacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY rosa_orientacoes_gestor ON public.rosa_orientacoes FOR SELECT TO authenticated USING(public.eh_gestor(auth.uid()) AND (tenant_id IS NULL OR public.has_tenant_access(tenant_id)));
CREATE POLICY rosa_orientacoes_servidor ON public.rosa_orientacoes FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE FUNCTION public.rosa_historico() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f uuid; c public.rosa_conversas; BEGIN f:=public.portal_cuidados_funcionario(); IF f IS NULL THEN RAISE EXCEPTION 'Acesso não autorizado' USING ERRCODE='42501'; END IF; INSERT INTO public.rosa_conversas(funcionario_id,tenant_id) SELECT id,tenant_id FROM public.funcionarios WHERE id=f ON CONFLICT(funcionario_id) DO NOTHING; SELECT * INTO c FROM public.rosa_conversas WHERE funcionario_id=f; RETURN jsonb_build_object('conversa_id',c.id,'funcionario_id',f,'tenant_id',c.tenant_id,'modulos',public.calcular_modulos_funcionario(f),'mensagens',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',m.id,'role',m.papel,'parts',m.partes) ORDER BY m.created_at,m.id) FROM public.rosa_mensagens m WHERE m.conversa_id=c.id),'[]'::jsonb),'orientacoes',COALESCE((SELECT jsonb_agg(orientacao_aprovada) FROM public.rosa_orientacoes WHERE status='aprovada' AND tenant_id IS NOT DISTINCT FROM c.tenant_id),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.rosa_historico() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.rosa_historico() TO anon,authenticated,service_role;
CREATE FUNCTION public.rosa_iniciar(p_pedido uuid,p_texto text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h jsonb; c public.rosa_conversas; BEGIN IF length(trim(p_texto)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Mensagem inválida'; END IF; h:=public.rosa_historico(); SELECT * INTO c FROM public.rosa_conversas WHERE id=(h->>'conversa_id')::uuid FOR UPDATE; IF EXISTS(SELECT 1 FROM public.rosa_mensagens WHERE conversa_id=c.id AND pedido_id=p_pedido) THEN RAISE EXCEPTION 'Pedido já recebido; consulte o histórico' USING ERRCODE='23505'; END IF; IF c.pedido_ativo IS NOT NULL AND c.iniciado_em>now()-interval '5 minutes' THEN RAISE EXCEPTION 'A Rosa já está respondendo' USING ERRCODE='55P03'; END IF; INSERT INTO public.rosa_mensagens(conversa_id,pedido_id,papel,partes) VALUES(c.id,p_pedido,'user',jsonb_build_array(jsonb_build_object('type','text','text',trim(p_texto)))); UPDATE public.rosa_conversas SET pedido_ativo=p_pedido,iniciado_em=now(),updated_at=now() WHERE id=c.id; RETURN public.rosa_historico(); END $$;
REVOKE ALL ON FUNCTION public.rosa_iniciar(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.rosa_iniciar(uuid,text) TO anon,authenticated,service_role;
CREATE FUNCTION public.rosa_finalizar(p_conversa uuid,p_pedido uuid,p_partes jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.rosa_conversas WHERE id=p_conversa AND pedido_ativo=p_pedido FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não ativo'; END IF; IF p_partes IS NOT NULL THEN INSERT INTO public.rosa_mensagens(conversa_id,pedido_id,papel,partes) VALUES(p_conversa,p_pedido,'assistant',p_partes) ON CONFLICT(conversa_id,pedido_id,papel) DO NOTHING; END IF; UPDATE public.rosa_conversas SET pedido_ativo=NULL,iniciado_em=NULL,updated_at=now() WHERE id=p_conversa; END $$;
REVOKE ALL ON FUNCTION public.rosa_finalizar(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.rosa_finalizar(uuid,uuid,jsonb) TO service_role;
CREATE FUNCTION public.rosa_revisar(p_id uuid,p_aprovar boolean,p_texto text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.eh_gestor(auth.uid()) THEN RAISE EXCEPTION 'Somente gestor' USING ERRCODE='42501'; END IF; IF p_aprovar AND length(trim(COALESCE(p_texto,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Orientação inválida'; END IF; UPDATE public.rosa_orientacoes SET status=CASE WHEN p_aprovar THEN 'aprovada' ELSE 'rejeitada' END,orientacao_aprovada=CASE WHEN p_aprovar THEN trim(p_texto) ELSE NULL END,revisado_por=auth.uid(),revisado_em=now(),updated_at=now() WHERE id=p_id AND (tenant_id IS NULL OR public.has_tenant_access(tenant_id)); IF NOT FOUND THEN RAISE EXCEPTION 'Sugestão indisponível'; END IF; END $$;
REVOKE ALL ON FUNCTION public.rosa_revisar(uuid,boolean,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.rosa_revisar(uuid,boolean,text) TO authenticated;